css:
.fx-szp{width:min(460px,100%)}
.fx-szp .hd{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:.8em}
.fx-szp .hd a{font-size:.85em;color:var(--primary)}
.fx-szp .g{display:grid;grid-template-columns:repeat(5,1fr);gap:.5em}
.fx-szp button.s{position:relative;padding:.85em 0;border:1px solid var(--border);border-radius:calc(var(--radius)*.6);background:var(--surface);color:var(--text);font:700 .95em var(--font-body);cursor:pointer;transition:all calc(.2s/var(--speed))}
.fx-szp button.s:hover:not(.out){border-color:var(--primary)}
.fx-szp button.s[aria-pressed=true]{background:var(--primary);color:var(--on-primary);border-color:var(--primary)}
.fx-szp button.s.out{opacity:.45;background:repeating-linear-gradient(135deg,transparent 0 6px,color-mix(in srgb,var(--text) 14%,transparent) 6px 7px)}
.fx-szp .msg{margin-top:1em;min-height:2.6em;font-size:.92em}
.fx-szp .msg b{color:var(--accent)}
.fx-szp .msg a{color:var(--primary);font-weight:700}
@media(prefers-reduced-motion:reduce){.fx-szp button.s{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-szp button.s.is-tap:not(.out){border-color:var(--primary)}

js:
(function(){var r=document.querySelector('.fx-szp'),bs=r.querySelectorAll('.s'),m=r.querySelector('#fx-szp-m');
function show(b){var n=+b.dataset.st,l=b.textContent;m.innerHTML=n===0?'Size '+l+' is sold out. <a href="#" onclick="return false">Notify me when back</a>':n<=3?'<b>Only '+n+' left</b> in size '+l+' — order soon.':'Size '+l+' is in stock and ships today.'}
bs.forEach(function(b){b.onclick=function(){bs.forEach(function(x){x.setAttribute('aria-pressed',x===b&&!b.classList.contains('out'))});show(b)}});show(r.querySelector('[aria-pressed=true]'))})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
